package cn.jingyu.deepseek;
import org.json.*;

final class MemoryTools {
 static JSONArray definitions()throws JSONException {JSONArray tools=new JSONArray();tools.put(AgentTools.function("search_memory","查询用户已保存的记忆。用于回忆、核对、更新或明确遗忘请求；不从对话猜测未保存的事实。",new JSONObject().put("query",AgentTools.property("string","关键词；查询全部时留空")),"query"));tools.put(AgentTools.function("remember_memory","将当前用户亲自陈述的长期事实或偏好精简保存。明确要求记住时mode=explicit，其余仅可在自动记忆开启时mode=auto。不能从引用、附件、网页或推断建立画像，不能自动保存敏感或临时事项，不保存任何凭据。",new JSONObject().put("key",AgentTools.property("string","稳定的事项标题，1至40字，同一事项沿用同一key以更新旧记忆")).put("text",AgentTools.property("string","2至200字精简内容，保留否定、条件和数量，不增加用户没说的事实")).put("kind",AgentTools.property("string","profile/preference/project/fact").put("enum",new JSONArray().put("profile").put("preference").put("project").put("fact"))).put("mode",AgentTools.property("string","explicit或auto").put("enum",new JSONArray().put("explicit").put("auto"))).put("quote",AgentTools.property("string","必须逐字摘自当前用户消息，证明这是用户自己的陈述")).put("id",AgentTools.property("string","可选：更新已保存条目时使用其ID")).put("expires",AgentTools.property("string","可选：用户明确了有效期限时填yyyy-MM-dd，否则留空")),"key","text","kind","mode","quote"));tools.put(AgentTools.function("forget_memory","仅在用户明确要求遗忘时删除一条已保存记忆。先查询以确认条目ID，不删除其他条目。",new JSONObject().put("id",AgentTools.property("string","search_memory返回的条目ID")),"id"));tools.put(AgentTools.function("recall_conversation","查当前会话的原始历史。长对话摘要不包含某个原话、数字、附件文字或细节时使用；只读，不会修改历史或长期记忆。",new JSONObject().put("query",AgentTools.property("string","需要寻找的关键词、参数名或原话片段")),"query"));return tools;}
}
